import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { OauthClientRepository } from 'app/features/access/oauth-client/repository/oauth-client-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { Component, inject } from '@angular/core';
import { OauthClient } from 'app/features/access/oauth-client/model/oauth-client.model';
import {
  OAUTH_CLIENT_EXCEL_COLUMNS,
  OAUTH_CLIENT_EXCEL_SENSITIVE,
} from 'app/features/access/oauth-client/model/oauth-client-excel-columns';

@Component({
  selector: 'oauth-client-view-export-action',
  standalone: false,
  templateUrl: './oauth-client-view-export-action.component.html',
})
export class OauthClientViewExportActionComponent extends BaseExportAction<OauthClient> {
  protected readonly scope = 'access/oauth-client';
  protected readonly repository = inject(OauthClientRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<OauthClient> = {
    name: 'access.oauth-client',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: OAUTH_CLIENT_EXCEL_COLUMNS,
    sensitive: OAUTH_CLIENT_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
